from lib import *
S = SS('w50')
steps = [
    step("把接收缓冲区塞满:接收方(客户端,connect 前设 SO_RCVBUF)不读数据,服务端用 TCP_NODELAY 每次写 1000 字节直到 send() 返回 EAGAIN。接收缓冲区读回 342972 字节;服务端的 send() 共让内核收下了 488000 字节,FIONREAD 显示接收方缓冲区里可读 342000 字节。接收方发出的 40 条 ACK 里没有窗口字段为 0 的;窗口的最后几个取值依次是 7976、5976、3976、2976、1976、976 字节——最后停在 976 字节,比服务端每次写的 1000 字节还小,所以窗口还没有恰好为 0,发送方就已经发不出下一个 1000 字节的包了。接收方把缓冲区的容量 342976 字节(342000 + 976)吃满,才会通告窗口 0。", t=tl(S(1)), mark=lidx(S(1), '接收方发出的 ACK', '窗口的最后几个取值'), done=lidx(S(1), '接收缓冲区 342972'), b=bars([['接收缓冲区', 342972, '342,972'], ['FIONREAD 可读', 342000, '342,000'], ['send() 收下', 488000, '488,000'], ['最后窗口', 976, '976']], 488000, mark=[3], done=[0, 1, 2]), kv=KV([['窗口序列', '… 7976 → 5976 → 3976 → 2976 → 1976 → 976'], ['停在', '976 字节 < 1000 字节的写入单位'], ['零窗口 ACK', '这一阶段 0 条,后面才出现']], ['停在'])),
    step("零窗口探测(persist 定时器):接收方一直不读,抓 25 秒。窗口恰好为 0 的 ACK 出现在抓包开始后 5.10 秒。之后 25 秒里发送方又发出了 4 个探测包,每个只带 1 字节载荷,序号(相对)都是 342976——就是窗口之外的下一个字节;距零窗口 +5.0、+10.0、+15.0、+20.0 秒,间隔固定 5.0 秒,没有看到指数增长。每个探测之后接收方回的 ACK 窗口字段都是 0、确认号不变:探测的那个字节没有被接收。net.inet.tcp.max_persist_timeout = 0,不设上限:只要连接还在就一直探测。必须有探测的原因:窗口更新是纯 ACK,不可靠;万一丢了,发送方就永远等不到窗口重新打开,探测让它能重新问到窗口。", t=tl(S(2)), mark=lidx(S(2), '探测 1:', '探测 2:', '探测 3:', '探测 4:'), done=lidx(S(2), '零窗口从', '相邻探测的间隔', '每个探测后接收方回的 ACK'), b=bars([['探测 1', 5.0, '+5.0 s'], ['探测 2', 10.0, '+10.0 s'], ['探测 3', 15.0, '+15.0 s'], ['探测 4', 20.0, '+20.0 s']], 20, mark=[0, 1, 2, 3], done=[]), kv=KV([['探测包', '1 字节载荷,序号 = 窗口之外的下一个字节'], ['间隔', '固定 5.0 秒'], ['接收方的回答', '窗口 0,确认号不变'], ['max_persist_timeout', '0:不设上限']], ['间隔'])),
    step("恢复:发送方的一个 send() 已经阻塞了 0.5 秒;接收方一读走 100000 字节,它马上发出“窗口更新”ACK——读之后 0.21 ms,窗口字段 33176(非 0,乘以缩放系数 8 就是约 26.5 万字节);第一个新数据包在读之后 0.58 ms 发出;被阻塞的 send() 在 1.3 ms 内返回。也就是说只要窗口更新 ACK 没丢,恢复几乎是即时的,不需要等 5 秒的探测。窗口更新 ACK 是纯 ACK,不会被重传;万一丢了,就靠第二节的探测包重新问到窗口。", t=tl(S(3)), mark=lidx(S(3), '读数据之后第一个'), done=lidx(S(3), '接收方在读数据之前', '窗口更新 ACK 是纯 ACK'), b=bars([['窗口更新 ACK(读之后)', 0.21, '0.21 ms'], ['第一个新数据包', 0.58, '0.58 ms'], ['被阻塞的 send() 返回', 1.3, '1.3 ms'], ['零窗口探测间隔', 5000, '5000 ms']], 5000, mark=[3], done=[0, 1, 2]), kv=KV([['窗口更新 ACK', '读之后 0.21 ms'], ['恢复发送', '0.58 ms 后第一个新数据包'], ['若更新 ACK 丢了', '最多等一个探测间隔(5 秒)']], ['若更新 ACK 丢了'])),
]
A = mkartw('w50', 50, '网络协议,TCP,零窗口,窗口探测,persist,窗口更新,真实验证,动画演示',
    '接收窗口缩到 976 字节(小于一次写入)后发送方停发,窗口为 0 后每 5.0 秒发一个 1 字节的探测包(固定间隔,不设上限);接收方一读数据,窗口更新 ACK 0.21 ms 就发出,被阻塞的 send() 在 1.3 ms 内返回。',
    '接收方处理不过来、窗口变成 0 之后,发送方怎么办?万一窗口重新打开的通知丢了会不会永远卡住?这篇把接收缓冲区塞满,抓发送方的零窗口探测包,再让接收方重新读数据看恢复要多久。',
    [('每 5.0 秒', '零窗口探测包的间隔(1 字节载荷,序号是窗口外的下一个字节),本机没有看到指数增长'), ('0.21 ms', '接收方读走数据后“窗口更新”ACK 发出的延迟(随后 0.58 ms 就有新数据)'), ('976 字节', '接收窗口的最后一个取值——比 1000 字节的写入单位还小,发送方已经发不动了')],
    [('窗口变成 0', '<p>接收方不读,窗口逐步缩小;小于发送方要发的包时就停发,等缓冲区吃满时通告窗口 0。</p>'),
     ('persist 探测', '<p>窗口 0 时发送方起一个 persist 定时器,每 5 秒发一个 1 字节的探测包,接收方回当前窗口。这样即使窗口更新 ACK 丢了也不会永远死锁。</p>'),
     ('恢复', '<p>接收方一读数据就主动发窗口更新 ACK,发送方毫秒级恢复;只有更新丢了才要等下一次探测。</p>')],
    steps,
    [ENV_W + '。全部在 lo0 上,接收方都在 connect 之前设置 SO_RCVBUF(实际缓冲区读回 342972 字节);第二节的 25 秒抓包期间接收方一直不读;窗口 = 窗口字段 × 2^3',
     '没有验证:探测间隔是否随失败次数增长到上限(只看了 4 次,固定 5.0 秒);窗口更新 ACK 丢失时的恢复(需要丢包);其它系统的 persist 定时器参数;零窗口时对端关闭或崩溃的探测行为'],
    '零窗口与窗口探测')
